-- Batch 02: reviewed internal project material pages, immutable source hashes.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v6';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; source_row jsonb; sub_batch int:=2; expected_before int:=25; expected_added int:=20;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v6_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 -- Serialize the brief data transaction against other writes, not normal reads.
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.project_material_library,public.project_material_library_pages IN SHARE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($spec$[{"lib":"0e8903a5-76e4-5c1e-83c9-4d6181c33a28","pg":8,"hash":"fd3e2d860dfd8f1ddafca8a21191ed493518ee742cc8d0da339ad92ff96fcd42","bid":"4c392bed-cc9f-48bd-9eb8-814d383b093b","f":"removable_floor","type":"boolean","unit":"boolean","pat":"(共23个楼层有可拆卸楼板)","note":"未入市项目历史设计资料，23个楼层设计有可拆卸楼板，并非已验收","mult":1,"addpat":null,"roundval":false},{"lib":"0e8903a5-76e4-5c1e-83c9-4d6181c33a28","pg":8,"hash":"fd3e2d860dfd8f1ddafca8a21191ed493518ee742cc8d0da339ad92ff96fcd42","bid":"4c392bed-cc9f-48bd-9eb8-814d383b093b","f":"elevator_zones","type":"text","unit":"configuration","pat":"(迅达高速电梯，目的选层系统，分区设置)","note":"未入市设计配置；仅记录分区设置，不推断分区数量","mult":1,"addpat":null,"roundval":false},{"lib":"0e8903a5-76e4-5c1e-83c9-4d6181c33a28","pg":8,"hash":"fd3e2d860dfd8f1ddafca8a21191ed493518ee742cc8d0da339ad92ff96fcd42","bid":"4c392bed-cc9f-48bd-9eb8-814d383b093b","f":"floor_load_office","type":"integer","unit":"kgf/m2 equivalent","pat":"楼板承重[[:space:]]+([0-9.]+) KN/㎡","note":"未入市设计办公楼板荷载3.5kN/㎡，按1kgf=9.80665N换算并四舍五入到整kgf/㎡；非实测","mult":101.97162129779284,"addpat":null,"roundval":false},{"lib":"9d4c9ef4-f616-511d-b043-c917cc2eb3d0","pg":23,"hash":"0cedc1d46ba1a5b040b5a046854fcef7b67fb0e8e540e8b6f830ae7d5c47df65","bid":"03ed56af-5fd0-4f90-aa80-89b5b694480a","f":"removable_floor","type":"boolean","unit":"boolean","pat":"(高区F26-F28 预留可拆卸楼板)","note":"未来项目设计预留，仅高区26—28层；不是已安装状态","mult":1,"addpat":null,"roundval":false},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","pg":5,"hash":"2bef57077e521824e9ba6a4017c5a20becc9429c47bc1133bb5e98dd618b9c43","bid":"1cba28c4-e3b9-403b-a7c0-362c870562e0","f":"grade","type":"text","unit":"brochure_positioning","pat":"全自持(甲级写字楼)","note":"历史业主推介对项目产品等级的原文定位，区别于高力主表产业园市场分类","mult":1,"addpat":null,"roundval":false},{"lib":"a78d673d-c177-52bd-8fae-18eae06ba960","pg":19,"hash":"db8dd51bb6bc4f6a8be64a3d27f62ed20fa6bf98e47dbd3d74757cb534313e54","bid":"c3a22c0d-d654-408a-bd77-609ee4eb9193","f":"facade_type","type":"text","unit":"configuration","pat":"(Low-E玻璃幕墙系统)","note":"历史项目双塔共用幕墙系统","mult":1,"addpat":null,"roundval":false},{"lib":"a78d673d-c177-52bd-8fae-18eae06ba960","pg":19,"hash":"db8dd51bb6bc4f6a8be64a3d27f62ed20fa6bf98e47dbd3d74757cb534313e54","bid":"c3a22c0d-d654-408a-bd77-609ee4eb9193","f":"standard_floor_area","type":"numeric","unit":"m2","pat":"([0-9]+)m²[[:space:]]+标准层面积","note":"推介资料所列标准层面积，约数；不采用有差异的总建面","mult":1,"addpat":null,"roundval":false},{"lib":"7ace123f-b76a-5ead-a594-17f8a409e21c","pg":7,"hash":"f8bd52b5b49c555fe866d52f26adc9847f15ca013cacc161579434ae983f50ac","bid":"e473db5a-1d4d-4ddf-9f2c-b2fae90919dc","f":"facade_type","type":"text","unit":"configuration","pat":"(框架及单元式玻璃幕墙体系，[[:space:]]*裙楼立面石材形成斜向壁柱)","note":"项目推介建筑外立面，非单个单元","mult":1,"addpat":null,"roundval":false},{"lib":"1121e64e-d60e-5334-bf63-be5f8e4abec0","pg":11,"hash":"fe22b26661de41875a840a01d0a3afe5274010bdfc76cc979383b646930970a1","bid":"47fee42f-9fc1-48a1-8aa6-19886edfb51b","f":"facade_type","type":"text","unit":"configuration","pat":"幕墙：(Low-E中空玻璃幕墙，拥有可开启扇)","note":"原项目推介幕墙系统","mult":1,"addpat":null,"roundval":false},{"lib":"56d040aa-8fb1-5044-b41e-baec00e52a1a","pg":12,"hash":"e9cc5d47f00312acfb2650f163082e3a3e413134c702e4fbad0396ee6cca2953","bid":"318735b6-d1fa-4918-ae4d-4fb265e23327","f":"parking_underground_floor","type":"integer","unit":"floors","pat":"车库[[:space:]]+B([0-9]+)-B[0-9]+","note":"车库位于B2至B4（含首末）共3层，不把B1商业计入地下停车层","mult":1,"addpat":"车库[[:space:]]+B[0-9]+-B([0-9]+)","roundval":false},{"lib":"62619c9f-926f-571d-b0f9-d2931d07bc7f","pg":3,"hash":"de80151aac75118c3260f42b1d07444dcfaaa5c96fc83af852940182539ccf6b","bid":"a1d32ac0-2380-4297-8856-5ba1b0fd9f08","f":"gfa_total","type":"numeric","unit":"m2","pat":"总建筑面积 Gross Floor Area[^\\n]*\\n[[:space:]]*([0-9.]+) 万㎡","note":"两版本项目整体总建筑面积均8万㎡；其他面积和停车位两版本不同不填","mult":10000,"addpat":null,"roundval":false},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":10,"hash":"19d908674ae741860500838ec11efda3ef0a0c6e0123aafe7ab79454fbc77bbc","bid":"f63cc0da-6082-41eb-b8bd-39f6ab037711","f":"floor_load_office","type":"integer","unit":"kgf/m2 equivalent","pat":"办公区域([0-9.]+)KN/sqm","note":"办公区域1.5kN/㎡，按1kgf=9.80665N换算整kgf/㎡，不采用首层10kN/㎡","mult":101.97162129779284,"addpat":null,"roundval":false},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","bid":"9ee3e3ff-4845-41a1-a78f-390c11b1917a","f":"floor_load_office","type":"integer","unit":"kgf/m2 equivalent","pat":"办公活荷载([0-9.]+)KN/㎡","note":"项目统一办公活荷载2.5kN/㎡，按1kgf=9.80665N换算整kgf/㎡；不采用商业4kN/㎡","mult":101.97162129779284,"addpat":null,"roundval":false},{"lib":"d2a705c7-1a4a-5794-8e8c-a5094049a56d","pg":25,"hash":"c96dbf113f4f340a85d5ddff1533c2863df0b97deb02c0bd28af3edd81a24db6","bid":"52061f7d-e204-4a30-b66d-3bf4654d9746","f":"floor_height","type":"numeric","unit":"m","pat":"2-4层 ([0-9.]+)米","note":"项目典型办公楼层2—4层为5.1m；首层5.7m、5层4.6m另有差别；另一页面列5.1m","mult":1,"addpat":null,"roundval":false},{"lib":"d2a705c7-1a4a-5794-8e8c-a5094049a56d","pg":25,"hash":"c96dbf113f4f340a85d5ddff1533c2863df0b97deb02c0bd28af3edd81a24db6","bid":"52061f7d-e204-4a30-b66d-3bf4654d9746","f":"standard_floor_area","type":"numeric","unit":"m2","pat":"单层面积[[:space:]]+([0-9,]+)平方米","note":"项目技术参数表的单层面积，原文为整体楼层非可租单元或单栋","mult":1,"addpat":null,"roundval":false},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","pg":5,"hash":"94b3f2091a58f3157d9bf0697dcdd56f36a1503255480955da368142c67b7a78","bid":"343dc130-a726-4a95-93c3-e0f4755fea9e","f":"gfa_total","type":"numeric","unit":"m2","pat":"地上建筑面积约([0-9.]+)㎡","note":"未来项目规划总建筑面积由地上47747和地下29993.18两明确同口径合计；约数四舍五入至平方米","mult":1,"addpat":"地下建筑面积约[[:space:]]*([0-9.]+)㎡","roundval":true},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","pg":5,"hash":"94b3f2091a58f3157d9bf0697dcdd56f36a1503255480955da368142c67b7a78","bid":"343dc130-a726-4a95-93c3-e0f4755fea9e","f":"gfa_retail","type":"numeric","unit":"m2","pat":"商业约([0-9.]+)㎡；地下建筑面积","note":"未来项目商业总建筑面积为地上约9696.07与地下约2343.59合计；约数四舍五入至平方米","mult":1,"addpat":"地下建筑面积约[[:space:]]*[0-9.]+㎡，其中商业约([0-9.]+)㎡","roundval":true},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","pg":20,"hash":"6ff1fda3051392af6225d9d619a8c6f41d323e775b8f162eae11e3ee357941c4","bid":"343dc130-a726-4a95-93c3-e0f4755fea9e","f":"elevator_passenger","type":"integer","unit":"count","pat":"A塔：客梯([0-9]+)部","note":"未来项目设计暂定A、B两塔各5部客梯，合计10；不包含转换、餐梯、消防梯或扶梯","mult":1,"addpat":"B塔：客梯([0-9]+)部","roundval":false},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","pg":20,"hash":"6ff1fda3051392af6225d9d619a8c6f41d323e775b8f162eae11e3ee357941c4","bid":"343dc130-a726-4a95-93c3-e0f4755fea9e","f":"power_backup_generator","type":"text","unit":"configuration","pat":"市政双路供电＋(柴油发电机重要负荷供电)","note":"未来项目设计备用电源配置；不推断安装完成或数量","mult":1,"addpat":null,"roundval":false},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","pg":11,"hash":"1d4fffdefb4dfc42ebc5fc26b162cd713bc07b513f274d6d6ffec0442558133b","bid":"343dc130-a726-4a95-93c3-e0f4755fea9e","f":"hvac_cooling_water_24h","type":"boolean","unit":"boolean","pat":"(预留24小时冷却水系统)","note":"未入市规划设计预留，非已投入运行","mult":1,"addpat":null,"roundval":false}]$spec$::jsonb) v(lib uuid,pg int,hash text,bid uuid,f text,type text,unit text,pat text,note text,mult numeric,addpat text,roundval boolean)), c AS (
SELECT b.id bid,b.name,d.id target_id,v.f field_name,CASE v.type WHEN 'numeric' THEN CASE WHEN v.roundval THEN to_jsonb(round(m.number_value)) ELSE to_jsonb(m.number_value) END WHEN 'integer' THEN to_jsonb(round(m.number_value)::int) WHEN 'boolean' THEN to_jsonb(true) ELSE to_jsonb(trim(regexp_replace(m1.val,'[[:space:]]+',' ','g'))) END new_value,v.type value_type,'project_material_library' source_table,l.id source_id,'page:'||v.pg source_field,'internal_archived_page' source_kind,v.unit,v.note||'; page_sha256='||v.hash note
FROM specs v JOIN public.project_material_library l ON l.id=v.lib JOIN public.project_material_library_pages p ON p.extraction_id=l.id AND p.page_number=v.pg AND p.content_sha256=v.hash JOIN public.buildings b ON b.id=v.bid JOIN public.building_brochure_data d ON d.building_id=b.id CROSS JOIN LATERAL (SELECT (regexp_match(p.content->>'native_text',v.pat))[1] val,CASE WHEN v.addpat IS NOT NULL THEN (regexp_match(p.content->>'native_text',v.addpat))[1] ELSE NULL END aval) m1 CROSS JOIN LATERAL (SELECT CASE WHEN v.type IN ('numeric','integer') THEN CASE WHEN v.f='parking_underground_floor' THEN replace(m1.aval,',','')::numeric-replace(m1.val,',','')::numeric+1 ELSE (replace(m1.val,',','')::numeric+coalesce(replace(m1.aval,',','')::numeric,0))*v.mult END END number_value) m
WHERE l.review_state='reviewed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(l.payload->'sections') s WHERE s->>'association_status'='confirmed' AND s->'candidate_building_ids' ? b.id::text AND jsonb_array_length(s->'candidate_building_ids')=1) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(l.payload->'sections') s WHERE s->>'association_status'='confirmed' AND NOT (s->'candidate_building_ids' ? b.id::text))
AND b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND (b.project_type='stock' OR (b.project_type='future' AND b.is_entered_market=false)) AND (SELECT count(*) FROM public.building_brochure_data y WHERE y.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND m1.val IS NOT NULL AND (v.addpat IS NULL OR m1.aval IS NOT NULL)
) SELECT c.* FROM c WHERE new_value IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p WHERE p.building_id=c.bid AND p.target_table='building_brochure_data' AND p.field_name=c.field_name) AND NOT EXISTS(SELECT 1 FROM public.audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=c.target_id::text AND (a.details->>'field_name'=c.field_name OR a.new_values ? c.field_name)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  VALUES(r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,CASE WHEN r.source_kind='internal_archived_page' THEN 'brochure' ELSE 'other' END,CASE WHEN r.source_kind='internal_archived_page' THEN 'secondary' ELSE 'legacy_unknown' END,CASE WHEN r.source_kind='internal_archived_page' THEN '高力国际已审阅历史项目资料' ELSE '高力国际内部已有业务记录' END,now_ts,now_ts,'legacy_backfill',ev,'batch_ref=ai_building_field_backfill_20261125_v6_100; source_table='||r.source_table||'; source_record_id='||r.source_id||'; source_field='||r.source_field||'; unit='||r.unit||'; '||r.note||'; AI-assisted',true);
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v6_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_table',r.source_table,'source_record_id',r.source_id,'source_field',r.source_field,'source_kind',r.source_kind,'unit',r.unit,'verification_status','legacy_backfill','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p JOIN public.audit_logs a ON a.event_id='ai_field_fill:'||ev::text WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value AND a.new_values->r.field_name=p.field_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected % qualifying fields, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
COMMIT;